class Solution {
public:
    int totalHammingDistance(vector<int>& nums) {
        long long ans = 0;
        int n = nums.size();
        for (int bit = 0; bit < 32; ++bit) {
            int cnt1 = 0;
            for (int x : nums) {
                cnt1 += (x >> bit) & 1;
            }
            int cnt0 = n - cnt1;
            ans += static_cast<long long>(cnt1) * cnt0;
        }
        return static_cast<int>(ans);
    }
};
